// Matrix Quiz data — a thin adapter over the generated masterfile.
//
// web/content/master.json is the single table the whole SynTutor reads (rule
// catalog + concept explanations + every quiz question). It is generated by
// `npm run build:master` from web/js/quiz/{catalog,concepts,s1..s11}.js. Do not
// hand-edit the sources here; edit those and regenerate.
//
// A quiz item is { bad, good, explanation }: `bad` is the incorrect sentence
// the learner must repair in the text box, `good` is the expected correction,
// and `explanation` says what is wrong in that item.

import MASTER from '../content/master.json' with { type: 'json' };
import { shuffle, diverseSample } from './quiz/index.js';
import { ruleDifficulty } from './quiz/catalog.js';

export { ruleDifficulty };

// Catalog — every rule in the matrix, grouped by section. Each rule carries its
// `difficulty` and its conceptual `concept` ("what this rule governs").
export const MATRIX_SECTIONS = MASTER.sections;

// Questions served per quiz run.
export const QUIZ_LENGTH = MASTER.quizLength;

// Rule complexity tiers. These classify a rule (shown beside it and used by the
// catalog filter) but do not change the quiz itself: the error a learner must
// fix is the same regardless of how complex the sentence gets.
export const DIFFICULTY = {
  easy: { label: 'Easy' },
  medium: { label: 'Medium' },
  hard: { label: 'Hard' },
};

export function hasQuiz(ruleId) {
  return Array.isArray(MASTER.questions[ruleId]) && MASTER.questions[ruleId].length > 0;
}

// Returns a shuffled, context-diverse slice of a rule's question pool.
export function questionPool(ruleId, limit = QUIZ_LENGTH) {
  const pool = MASTER.questions[ruleId];
  if (!Array.isArray(pool) || !pool.length) return [];
  return diverseSample(shuffle(pool), Math.max(0, limit));
}

export function ruleInfo(ruleId) {
  for (const section of MATRIX_SECTIONS) {
    const found = section.rules.find((r) => r.id === ruleId);
    if (found) return {
      ...found,
      section: section.title,
      sectionId: section.id,
    };
  }
  return null;
}
